parameters.jsCode:
// Parsed Claude response → flat fields for downstream nodes
const item = $input.first().json;

// Anthropic Messages API returns { content: [{ type: 'text', text: '...' }], ... }
const raw = (item.content && item.content[0] && item.content[0].text) || item.completion || '';

let parsed;
try {
  // strip potential markdown fences just in case
  const cleaned = raw.trim().replace(/^```(?:json)?/i, '').replace(/```$/,'').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error('Claude hat kein gültiges JSON geliefert: ' + raw);
}

// Build output
return [{
  json: {
    ai_analysis: parsed.ai_analysis || '',
    root_cause: parsed.root_cause || '',
    solution_approach: parsed.solution_approach || '',
    priority: parsed.priority || 'Middle',
    actions: Array.isArray(parsed.actions) ? parsed.actions : []
  }
}];
